content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Visitor",
      "description": "Person who comes to the museum"
    },
    {
      "name": "Admission Ticket",
      "description": "Ticket that lets a visitor enter exhibits",
      "attributes": [
        "Exhibit"
      ]
    },
    {
      "name": "Guided Tour",
      "description": "Tour that gives visitors curated explanations"
    },
    {
      "name": "Curator",
      "description": "Staff member who creates and manages exhibits"
    },
    {
      "name": "Exhibit",
      "description": "Museum presentation that shows selected artifacts",
      "attributes": [
        "Artifact",
        "Exhibit Description"
      ]
    },
    {
      "name": "Artifact",
      "description": "Historical or artistic item in the museum"
    },
    {
      "name": "Exhibit Description",
      "description": "Text that explains an artifact or exhibit"
    },
    {
      "name": "Conservator",
      "description": "Specialist who protects and restores artifacts"
    },
    {
      "name": "Restoration Evaluation",
      "description": "Check of an artifact to see how much repair it needs"
    },
    {
      "name": "Preservation Treatment",
      "description": "Work done to stabilize or protect an artifact"
    },
    {
      "name": "Education Coordinator",
      "description": "Staff member who organizes workshops and learning offers"
    },
    {
      "name": "Workshop",
      "description": "Interactive learning session for visitors or school groups",
      "attributes": [
        "Learning Material"
      ]
    },
    {
      "name": "Learning Material",
      "description": "Handouts or digital material used in workshops"
    },
    {
      "name": "Museum Store Manager",
      "description": "Person who handles shop items and sales"
    },
    {
      "name": "Sales Trends Review",
      "description": "Look at recent sales to decide what to restock"
    },
    {
      "name": "Merchandise Item",
      "description": "Store product often linked to an exhibit",
      "attributes": [
        "Exhibit"
      ]
    },
    {
      "name": "Museum Coordinator",
      "description": "Person who oversees scheduling across the museum"
    },
    {
      "name": "Museum Schedule",
      "description": "Plan that lists exhibitions and workshops",
      "attributes": [
        "Exhibit",
        "Workshop"
      ]
    }
  ]
}
```
